"""Build ASPI, LAES, ZETA's 2026-11-27 evidence bundles and reports.

Inputs are reviewed official-source notes in docs/reports/specialty-refresh-inputs-20261127.json.
Templates and reference calculation/validator are the user-provided report-generation-materials.
This script never changes the shared stocks, prices or signals files.
"""
from __future__ import annotations
import argparse,importlib.util,json,math,re
from datetime import datetime,timezone
from pathlib import Path
from generate_eli_lilly_reports import esc,usd,pct,row,bullets,detail,guide_box,signal,render
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-11-27'

def build(profile,materials):
    spec=importlib.util.spec_from_file_location('calc',materials/'10_calculation_reference.py');calc=importlib.util.module_from_spec(spec);spec.loader.exec_module(calc)
    x=profile;p=x['quote']['meta']['regularMarketPrice'];qmeta=x['quote']['meta'];asof=datetime.fromtimestamp(qmeta['regularMarketTime'],timezone.utc).isoformat();now=datetime.now(timezone.utc).isoformat();N=x['N'];case_inputs=x['inputs'];claims=[]
