    xs=[c['price'] for c in cases];ev=calc.expected_price(xs,[v['prob'] for v in case_inputs]);raw,clipped=calc.band_position(p,xs[0],xs[2]);c=dict(expected_price=ev,expected_delta_pct=calc.pct_change(ev,p),raw_band_position_pct=raw,display_band_position_pct=clipped,endpoint_rr=calc.endpoint_rr(p,xs[0],xs[2]),market_score=calc.market_score(p,xs[0],xs[2]),own_score=calc.own_score(ev,xs[0],xs[2]),supplemental_score=calc.supplemental_score(p,ev,xs[0],case_inputs[0]['prob']))
