                rejected=[dict(method=v['method'],status='NOT_APPLICABLE',reason='新規事業価値・調達収入のない直接上場で、独立価値入力や比較可能な価格反応標本がないため。') for v in attempts]
                outcomes.append(dict(label=label,conditions=[condition],direction='MIXED',quantifiable=False,price_range=None,price_change_pct_range=None,probability=None,method_note=no_price['reason'],quantification_attempts=rejected,non_quantified_explanation=no_price))
