            outcomes.append(dict(label=label,conditions=[condition],direction=direction,quantifiable=True,price_range=pr,price_change_pct_range=[calc.pct_change(v,p) for v in pr],probability=None,method_note=note,quantification_attempts=attempts,non_quantified_explanation=None))
