    cap=dict(basic_shares=x['basic'],diluted_shares=N,market_cap=p*N,cash=x['cash'],liquid_securities=0,restricted_cash=x['restricted'],minimum_operating_cash=0,debt=x['debt'],preferred_stock=0,minority_interest=x['nci'],other_non_equity_claims=0,ttm_operating_cash_flow=None,ttm_capex=None,burn_one_off_adjustments=None,runway_months=None,source_ids=refs,dilution_notes=[t for a,t in x['facts'] if '株式' in a]+[x['finance_note'],'TTMランウェイは事業再編・買収前後の期間が一致しないため未算出。最近のCFと期末現金、会社の資金見通しを本文で別々に説明。0の換金性資産等は追加価値を仮定しない入力方針で、存在しないとの断定ではない。'])
    sources=[dict(id=id,title=title,publisher=x['legal']+' / SEC',url=url,published_at=pub,accessed_at=now,source_type=typ,is_primary=True,supports_claim_ids=[c['id'] for c in claims if id in c['source_ids']]) for id,title,url,pub,typ in x['sources']]
    quote_url='https://query1.finance.yahoo.com/v8/finance/chart/'+x['ticker']+'?range=3mo&interval=1d';sources.append(dict(id='SQUOTE',title='Yahoo Finance価格・日足（暫定取得元）',publisher='Yahoo Finance',url=quote_url,published_at=None,accessed_at=now,source_type='MARKET_DATA',is_primary=False,supports_claim_ids=['QUOTE_STATS']))
    next(c for c in claims if c['id']=='QUOTE_STATS')['source_ids']=['SQUOTE']
    bundle=dict(meta=dict(framework_version='6.2',schema_version='1.2',company_name=x['legal'],ticker=x['ticker'],exchange=x['exchange'],currency='USD',fiscal_year_end='12-31',valuation_date=DATE,source_cutoff=now,generated_at=now,price=p,price_as_of=asof,benchmark='S&P 500（相対リターン未採用）'),capital_structure=cap,claims=claims,sources=sources,guide=dict(tagline=x['business'],section_claim_ids={f'sec{i}':[f'F{j+1}' for j in range(len(x['facts']))] for i in range(1,8)},source_ids=refs),scenario=dict(horizon_date='2027-12-31',primary_method=x['method'],method_explanation='2027年末事業価値＋同時点自由現金−負債−非支配持分＝株主価値。これを同じケースの将来株式数で割る。'+x['model_note'],cases=cases,computed=c,risk_class='HIGH' if x['ticker']!='ZETA' else 'MEDIUM',risk_reasons=[x['risks']],major_catalyst_id='C1',sensitivity=[dict(variable='標準事業価値（USD）',low=case_inputs[1]['ev']*.8,base=case_inputs[1]['ev'],high=case_inputs[1]['ev']*1.2,result_prices=[(v+case_inputs[1]['cash']-x['debt']-x['nci'])/case_inputs[1]['shares'] for v in [case_inputs[1]['ev']*.8,case_inputs[1]['ev'],case_inputs[1]['ev']*1.2]]),dict(variable='標準の将来株式数',low=case_inputs[1]['shares']*.9,base=case_inputs[1]['shares'],high=case_inputs[1]['shares']*1.1,result_prices=[cases[1]['equity_value']/v for v in [case_inputs[1]['shares']*.9,case_inputs[1]['shares'],case_inputs[1]['shares']*1.1]])],distribution_method='THREE_POINT',monte_carlo=None),catalyst_report=dict(status='CATALYST_RICH',next_catalyst_id='C1',catalysts=catalysts,dependency_groups=[dict(id='G1',name='共通事業価値・資金・採用',relationship_type='SHARED_VALUE',catalyst_ids=[a['id'] for a in catalysts],aggregation_rule='同じ事業価値への影響を1回のみ計上し、個別価格幅・割合を加算しない。',full_success_incremental_equity_value=increment)],overall_priced_in=dict(quantifiable=True,percent_range=[max(0,min(100,over-10)),max(0,min(100,over+10))],raw_implied_pct=over,all_events_excluded_equity_value=loweq,included_group_ids=['G1'],method_note='標準の現金・負債・少数株主請求権を固定し共通事業価値の悲観・楽観端点から逆算。個別割合の平均ではない。表示は主観的な±10ポイント幅を0～100へ制限するが、生の値が範囲外なら本文に残す。真の成功確率や統計区間ではない。',confidence='LOW',non_quantified_explanation=None),watch_items=[dict(item=a['title'],frequency='公式発表・次の決算時',update_trigger='進捗、現金、資金・株式数と採用条件の変更',catalyst_ids=[a['id']]) for a in catalysts]),validation_summary=dict(status='WARN',fail_count=0,warn_count=len(warning),generated_at=now,messages=warning))
