def render_reports(x,b,materials):
    meta,sc,cat,cap=(b[k] for k in ['meta','scenario','catalyst_report','capital_structure']);c=sc['computed'];p=meta['price'];cases=sc['cases'];bear,base,bull=cases
    back='<a href="../../index.html">SiM MARKET LABの銘柄一覧へ戻る</a>';sources='<ul>'+''.join(f'<li><a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">{esc(s["id"]+"："+s["title"])}</a>（公表{esc(s["published_at"] or "時刻別価格")}／取得{DATE}）</li>' for s in b['sources'])+'</ul>'
    fact_sources='['+','.join(s['id'] for s in b['sources'] if s['is_primary'])+']'
    def blocks(items):return '<div class="info-row">'+''.join(guide_box(a,esc(v)) for a,v in items)+'</div>'
    facts=[(a,v+' '+fact_sources) for a,v in x['facts']]
    warning='将来価値・支出・確率・株式数は当方の条件付き仮定です。最新の確定財務と分析基準日を分けて表示しています。'+x['risks']
    basis=f'分析基準日{DATE}。株価{usd(p)}／{meta["price_as_of"]}。分析対象2027年末。価格表示が更新されても分析値は固定。'
    disclaimer='情報提供・教育目的の資料です。投資助言・売買推奨ではありません。予測値・主観確率・資産価値は仮定で、実現や価格収束を保証しません。配当は価格比較に含みません。'
